<?php
require __DIR__.'/../includes/bootstrap.php'; require_admin($conn);
$id=(int)($_GET['id']??0); $st=$conn->prepare("SELECT * FROM books WHERE id=?"); $st->bind_param('i',$id); $st->execute(); $book=$st->get_result()->fetch_assoc();
if(!$book) exit('Book not found.'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $title=post_string('title',200); $author=post_string('author',150); $desc=post_string('description',4000); $cat=(int)($_POST['category_id']??0); $price=(float)($_POST['price']??0); $stock=max(0,(int)($_POST['stock']??0));
try{$cover=valid_image_upload($_FILES['cover']??[]); if(!$title||!$author||!$cat||$price<0) throw new RuntimeException('Complete all required fields.');
if($cover){$st=$conn->prepare("UPDATE books SET category_id=?,title=?,author=?,description=?,price=?,stock=?,cover_image=? WHERE id=?");$st->bind_param('isssdisi',$cat,$title,$author,$desc,$price,$stock,$cover,$id);}
else{$st=$conn->prepare("UPDATE books SET category_id=?,title=?,author=?,description=?,price=?,stock=? WHERE id=?");$st->bind_param('isssdii',$cat,$title,$author,$desc,$price,$stock,$id);}
$st->execute(); flash('success','Book updated.'); redirect('admin/books.php');}catch(Throwable $e){$error=$e->getMessage();}}
$cats=$conn->query("SELECT id,name FROM categories ORDER BY name")->fetch_all(MYSQLI_ASSOC); $pageTitle='Edit book'; require __DIR__.'/../includes/header.php';?>
<section class="container section"><form method="post" enctype="multipart/form-data" class="admin-form"><?=csrf_field()?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><h1>Edit book</h1><div class="form-grid"><label>Title<input name="title" value="<?=e($book['title'])?>" required></label><label>Author<input name="author" value="<?=e($book['author'])?>" required></label><label>Category<select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$book['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Price<input name="price" type="number" min="0" step=".01" value="<?=e($book['price'])?>" required></label><label>Stock<input name="stock" type="number" min="0" value="<?=e($book['stock'])?>" required></label><label>Cover<input type="file" name="cover" accept="image/jpeg,image/png,image/webp"></label></div><label>Description<textarea name="description"><?=e($book['description'])?></textarea></label><button class="btn btn-dark">Save changes</button></form></section><?php require __DIR__.'/../includes/footer.php';?>